<script setup lang="ts">
import { computed, ref } from 'vue';
import { Link, useForm, usePage } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import { ArrowRight, CheckCircle2, Gauge, Plus, Ruler, Scale, TrendingDown, TrendingUp, Volleyball, X } from '@lucide/vue';
type Assessment = { id: number; date: string; height_cm: number | null; weight_kg: number | null; standing_reach_cm: number | null; vertical_jump_cm: number | null; spike_reach_cm: number | null; block_reach_cm: number | null; agility_seconds: number | null; coach_notes: string | null; recorder: string | null };
type Athlete = { id: number; name: string; membership_number: string; team: string | null; position: string | null; jersey_number: number | null };
const props = defineProps<{ athlete: Athlete | null; assessments: Assessment[]; progress: Record<string, number | null>; canRecord: boolean }>();
const page = usePage(); const successMessage = computed(() => page.props.flash?.success as string | null); const showForm = ref(false);
const latest = computed(() => props.assessments[0] || null);
const iranToday = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Tehran', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const form = useForm({ assessment_date: iranToday, height_cm: null as number | null, weight_kg: null as number | null, standing_reach_cm: null as number | null, vertical_jump_cm: null as number | null, spike_reach_cm: null as number | null, block_reach_cm: null as number | null, agility_seconds: null as number | null, coach_notes: '' });
const submit = () => { if (props.athlete) form.post(`/assessments/${props.athlete.id}`, { preserveScroll: true, onSuccess: () => { showForm.value = false; form.reset(); } }); };
const dateLabel = (value: string) => new Intl.DateTimeFormat('fa-IR', { day: 'numeric', month: 'long', year: 'numeric' }).format(new Date(`${value}T12:00:00`));
const progressLabel = (metric: string, reverse = false) => { const value = props.progress[metric]; if (value === null || value === undefined) return 'بدون مقایسه'; const improved = reverse ? value < 0 : value > 0; return `${value > 0 ? '+' : ''}${value} ${improved ? 'پیشرفت' : value === 0 ? 'بدون تغییر' : 'کاهش'}`; };
const barHeight = (value: number | null, key: 'vertical_jump_cm' | 'spike_reach_cm') => { if (!value) return '4%'; const values = props.assessments.map(item => item[key] || 0); const min = Math.min(...values); const max = Math.max(...values); return `${25 + ((value - min) / Math.max(1, max - min)) * 70}%`; };
</script>
<template><AppLayout :title="athlete ? `ارزیابی ${athlete.name}` : 'ارزیابی ورزشی'" eyebrow="پاسپورت عملکرد والیبال" active="athlete">
<section v-if="!athlete" class="panel-flat p-10 text-center"><h2 class="text-base font-black">پرونده ورزشکاری متصل نیست</h2><p class="mt-2 text-[10px] text-[#849098]">برای نمایش رکوردها، مدیر باشگاه باید حساب را به ورزشکار متصل کند.</p></section>
<template v-else><div class="mb-4 flex items-center justify-between"><Link v-if="canRecord" href="/assessments" class="inline-flex items-center gap-2 text-[10px] font-black text-[#657580]"><ArrowRight :size="15" /> بازگشت به ورزشکاران</Link><span v-else /><button v-if="canRecord" class="primary-sport-button" @click="showForm = true"><Plus :size="16" /> ثبت ارزیابی جدید</button></div><div v-if="successMessage" class="mb-4 flex items-center gap-2 border border-[#bcd9ca] bg-[#edf7f1] px-4 py-3 text-[11px] font-bold text-[#236b54]"><CheckCircle2 :size="16" />{{ successMessage }}</div>
<section class="athlete-pass mb-5"><div class="athlete-avatar">{{ athlete.name.slice(0, 2) }}</div><div class="relative z-10 flex-1"><p class="text-[9px] font-bold text-[#f29a66]">{{ athlete.membership_number }}</p><h2 class="mt-1 text-xl font-black text-white">{{ athlete.name }}</h2><p class="mt-2 text-[10px] text-[#b7c5cf]">{{ athlete.team }} · {{ athlete.position || 'بدون پست' }}</p></div><div v-if="latest" class="athlete-status"><CheckCircle2 :size="14" />آخرین ارزیابی {{ dateLabel(latest.date) }}</div></section>
<section v-if="latest" class="mb-5 grid grid-cols-2 gap-3 md:grid-cols-4 xl:grid-cols-7"><article v-for="metric in [{k:'height_cm',l:'قد',u:'cm',i:Ruler},{k:'weight_kg',l:'وزن',u:'kg',i:Scale},{k:'vertical_jump_cm',l:'پرش عمودی',u:'cm',i:TrendingUp},{k:'standing_reach_cm',l:'دسترسی ایستاده',u:'cm',i:Gauge},{k:'spike_reach_cm',l:'دسترسی اسپک',u:'cm',i:Volleyball},{k:'block_reach_cm',l:'دسترسی دفاع',u:'cm',i:Volleyball},{k:'agility_seconds',l:'چابکی',u:'sec',i:TrendingDown}]" :key="metric.k" class="record-metric"><component :is="metric.i" :size="17" /><span>{{ metric.l }}</span><strong>{{ latest[metric.k as keyof Assessment] ?? '—' }} <small>{{ metric.u }}</small></strong><em>{{ progressLabel(metric.k, metric.k === 'agility_seconds') }}</em></article></section>
<section class="grid gap-5 xl:grid-cols-[.75fr_1.25fr]"><article class="panel-flat p-5"><div><p class="section-kicker">روند پرش عمودی</p><h3 class="mt-1 text-sm font-black">پیشرفت در ارزیابی‌ها</h3></div><div class="trend-chart"><div v-for="item in [...assessments].reverse()" :key="item.id" class="trend-column"><strong>{{ item.vertical_jump_cm }}</strong><i :style="{ height: barHeight(item.vertical_jump_cm, 'vertical_jump_cm') }" /><span>{{ dateLabel(item.date) }}</span></div></div><p v-if="latest?.coach_notes" class="mt-5 border-r-2 border-[#e87532] pr-3 text-[10px] leading-6 text-[#5e6d77]">{{ latest.coach_notes }}</p></article><article class="panel-flat overflow-hidden"><header class="panel-head"><div><h3>تاریخچه کامل رکوردها</h3><p>{{ assessments.length }} ارزیابی ثبت شده</p></div></header><div class="overflow-x-auto"><table class="sport-table assessment-history"><thead><tr><th>تاریخ</th><th>قد</th><th>پرش</th><th>اسپک</th><th>دفاع</th><th>چابکی</th><th>ثبت‌کننده</th></tr></thead><tbody><tr v-for="item in assessments" :key="item.id"><td><strong>{{ dateLabel(item.date) }}</strong></td><td>{{ item.height_cm ?? '—' }}</td><td>{{ item.vertical_jump_cm ?? '—' }}</td><td>{{ item.spike_reach_cm ?? '—' }}</td><td>{{ item.block_reach_cm ?? '—' }}</td><td>{{ item.agility_seconds ?? '—' }}</td><td>{{ item.recorder || '—' }}</td></tr></tbody></table></div></article></section>
<div v-if="showForm" class="modal-shell" @click.self="showForm = false"><section class="modal-card sm:!max-w-3xl"><header class="modal-head"><div><p class="section-kicker">رکوردگیری جدید</p><h2>{{ athlete.name }}</h2></div><button @click="showForm = false"><X :size="20" /></button></header><form class="space-y-5 p-5" @submit.prevent="submit"><div class="grid gap-4 sm:grid-cols-3"><label class="form-label">تاریخ ارزیابی<input v-model="form.assessment_date" type="date" class="form-input" dir="ltr"></label><label class="form-label">قد (cm)<input v-model="form.height_cm" type="number" step="0.1" class="form-input"></label><label class="form-label">وزن (kg)<input v-model="form.weight_kg" type="number" step="0.1" class="form-input"></label><label class="form-label">دسترسی ایستاده (cm)<input v-model="form.standing_reach_cm" type="number" step="0.1" class="form-input"></label><label class="form-label">پرش عمودی (cm)<input v-model="form.vertical_jump_cm" type="number" step="0.1" class="form-input"></label><label class="form-label">دسترسی اسپک (cm)<input v-model="form.spike_reach_cm" type="number" step="0.1" class="form-input"></label><label class="form-label">دسترسی دفاع (cm)<input v-model="form.block_reach_cm" type="number" step="0.1" class="form-input"></label><label class="form-label">آزمون چابکی (ثانیه)<input v-model="form.agility_seconds" type="number" step="0.01" class="form-input"></label></div><label class="form-label">یادداشت مربی<textarea v-model="form.coach_notes" class="form-textarea" rows="3"></textarea></label><div class="flex justify-end gap-2"><button type="button" class="secondary-button" @click="showForm = false">انصراف</button><button class="primary-sport-button" :disabled="form.processing">ثبت رکورد و به‌روزرسانی نمودار</button></div></form></section></div>
</template></AppLayout></template>
